function candidate(id: string, accessibleName: string, order: number): InteractionCandidate {
  return {
    id,
    domOrder: order,
    tag: 'button',
    role: 'button',
    accessibleName,
    text: accessibleName,
    href: null,
    elementType: 'button',
    ariaLabel: null,
    title: null,
    ariaExpanded: null,
    ariaSelected: null,
    disabled: false,
    visible: true,
    formAssociated: false,
    submitsForm: false,
    fileUpload: false,
    testId: null,
    label: null,
    stableId: null,
    locator: { strategy: 'role', role: 'button', name: accessibleName, index: 0 },
  };
}

